import{_ as r,C as i,o as s,c as n,ak as c,E as o,j as e,a}from"./chunks/framework.DxrHb2fb.js";const x=JSON.parse('{"title":"EmptyState 空状态","description":"","frontmatter":{},"headers":[],"relativePath":"components/empty-state.md","filePath":"components/empty-state.md","lastUpdated":1790043131000}'),l={name:"components/empty-state.md"};function h(p,t,m,u,b,f){const d=i("XhDemo");return s(),n("div",null,[t[0]||(t[0]=c('<h1 id="emptystate-空状态" tabindex="-1">EmptyState 空状态 <a class="header-anchor" href="#emptystate-空状态" aria-label="Permalink to &quot;EmptyState 空状态&quot;">​</a></h1><p>没有数据时的占位区域：说明为什么为空，以及可以做什么。</p><p>空状态与结果页共用同一套结构：图标、标题、说明、操作四段与整页结果完全一致，404、403、500 等结果页也使用本组件。<code>status</code> 只接受这三个状态码，只落为 root 的 <code>data-status</code>，皮肤据此把图标区并入最接近的一族语气色，不改变语义、不带插画资源；成功、警示、出错、提示等通用结果使用全库统一的 <code>tone</code> 轴。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/empty-state" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/empty-state.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/empty-state" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/empty-state" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/empty-state.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>图标、标题、说明、操作四个槽都可选，只有 root 是必需的</p>',6)),o(d,{src:"empty-state/01-basic"}),t[1]||(t[1]=c('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;empty-state&quot;</code>：<strong><code>root</code></strong> · <code>media</code> · <code>indicator</code> · <code>title</code> · <code>description</code> · <code>action</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="尺寸" tabindex="-1">尺寸 <a class="header-anchor" href="#尺寸" aria-label="Permalink to &quot;尺寸&quot;">​</a></h3><p>size 只改变留白与字号，语义不变；不传即 md</p>',6)),o(d,{src:"empty-state/02-size"}),t[2]||(t[2]=e("h3",{id:"播报方式",tabindex:"-1"},[a("播报方式 "),e("a",{class:"header-anchor",href:"#播报方式","aria-label":'Permalink to "播报方式"'},"​")],-1)),t[3]||(t[3]=e("p",null,"默认 polite 使 root 成为活区，筛选完成后就地播报；off 使它只是一个普通容器",-1)),o(d,{src:"empty-state/03-live"}),t[4]||(t[4]=e("h3",{id:"用作结果页",tabindex:"-1"},[a("用作结果页 "),e("a",{class:"header-anchor",href:"#用作结果页","aria-label":'Permalink to "用作结果页"'},"​")],-1)),t[5]||(t[5]=e("p",null,"同一套部件也承载 404、403 等结果：status 为图标区上语气色，操作槽中放置回退出口",-1)),o(d,{src:"empty-state/04-result"}),t[6]||(t[6]=e("h3",{id:"图标自带语气",tabindex:"-1"},[a("图标自带语气 "),e("a",{class:"header-anchor",href:"#图标自带语气","aria-label":'Permalink to "图标自带语气"'},"​")],-1)),t[7]||(t[7]=e("p",null,"图标槽中放置一个带 tone 的图标，着色落在图标自身上，不经过根上的 tone",-1)),o(d,{src:"empty-state/05-tone-icon"}),t[8]||(t[8]=e("h3",{id:"颜色",tabindex:"-1"},[a("颜色 "),e("a",{class:"header-anchor",href:"#颜色","aria-label":'Permalink to "颜色"'},"​")],-1)),t[9]||(t[9]=e("p",null,"tone 为图标区上语气色，与全库同一根轴；绘制什么图标仍由作者放置",-1)),o(d,{src:"empty-state/06-tone"}),t[10]||(t[10]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>列表、表格、搜索结果为空。</li><li>首次使用、还没有任何数据。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>数据加载中时，使用<a href="./skeleton">骨架屏</a>或<a href="./spinner">加载指示器</a>。</li><li>一次轻量操作的反馈使用<a href="./toast">轻提示</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>图标、标题、描述、操作四段都可选。</li><li><code>live</code> 决定内容出现时读屏如何播报，搜索结果变空时尤其重要。</li><li><code>status</code> 只接受 404 / 403 / 500 三个状态码，各并入最接近的一族语气色；<code>tone</code> 直接指定语气，两者都写时以 <code>tone</code> 为准。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>图标使用<a href="./icon-wrapper">图标块</a>；操作使用<a href="./button">按钮</a>。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>区分三种空：从未有数据、筛选后为空、搜索无结果，三者的文案完全不同。</li><li>提供一条出路：新建、清除筛选、更换关键词。</li><li>用作结果页时每一页都提供回退出口：回首页、重试、联系支持，403 与 500 尤其需要。</li><li>失败页提供可追溯的标识（请求号、时间），便于用户报障。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>只显示一个空盒子加“暂无数据”，用户不知道下一步做什么。</li><li>首次使用的空状态与筛选无结果的外观相同。</li><li>只写“出错了”，不说明错误内容，也不提供下一步。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-empty-state&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhEmptyStateAction</code> <code>XhEmptyStateDescription</code> <code>XhEmptyStateIndicator</code> <code>XhEmptyStateMedia</code> <code>XhEmptyStateRoot</code> <code>XhEmptyStateTitle</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/empty-state.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>live</code></td><td><code>EmptyStateLive</code></td><td></td><td>默认 polite。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸档位，只影响留白与字号，不改变语义。</td></tr><tr><td><code>status</code></td><td><code>EmptyStateStatus</code></td><td></td><td>结果页的状态码，只写为 root 的 data-status；皮肤据此把图标区并入最接近的一族语气色，图标内容由作者放入图标槽。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定图标区使用哪族颜色；与 status 都提供时以它为准。未提供时保持中性。</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>live</code></td><td><code>EmptyStateLive</code></td><td>生效的播报方式，默认值补齐后的结果。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMediaProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>插画槽：按自身的尺寸档测量，与字形槽二选一。</td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getActionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/live-regions/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>role</code></td><td>undefined | &#39;status&#39;</td></tr><tr><td><code>media</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/empty-state.css</code> 使用 <code>[data-scope=&quot;empty-state&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-status</code></td><td>props.status</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-empty-state-action-gap</code></td><td><code>action</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>empty-state 的 action 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-description-fg</code></td><td><code>description</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>empty-state 的 description 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-description-font-size</code></td><td><code>description</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-secondary-size</code></td><td>empty-state 的 description 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-description-leading</code></td><td><code>description</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-leading-normal</code></td><td>empty-state 的 description 部件 line-height 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-description-max-w</code></td><td><code>description</code></td><td><code>max-inline-size</code></td><td><code>default</code></td><td><code>--xh-measure-prose</code></td><td>empty-state 的 description 部件 max-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>empty-state 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_empty-state-gap</code></td><td>empty-state 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-icon-size</code></td><td><code>indicator</code></td><td><code>--xh-icon-size</code><br><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-_empty-state-icon-size</code></td><td>empty-state 的 indicator 部件 --xh-icon-size、block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-indicator-fg</code></td><td><code>indicator</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_empty-state-accent</code></td><td>empty-state 的 indicator 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-indicator-font-size</code></td><td><code>indicator</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_empty-state-icon-size</code></td><td>empty-state 的 indicator 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-media-fg</code></td><td><code>media</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_empty-state-accent</code></td><td>empty-state 的 media 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-media-size</code></td><td><code>media</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-_empty-state-icon-size</code></td><td>empty-state 的 media 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-px</code></td><td><code>root</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-space-6</code></td><td>empty-state 的 root 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-py</code></td><td><code>root</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-_empty-state-py</code></td><td>empty-state 的 root 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-title-fg</code></td><td><code>title</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>empty-state 的 title 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-title-font-size</code></td><td><code>title</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_empty-state-title-size</code></td><td>empty-state 的 title 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-title-font-weight</code></td><td><code>title</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-semibold</code></td><td>empty-state 的 title 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-title-leading</code></td><td><code>title</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-leading-tight</code></td><td>empty-state 的 title 部件 line-height 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>共享关键帧 <code>xh-rise-in</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',42))])}const g=r(l,[["render",h]]);export{x as __pageData,g as default};
